-- Fixed Dummy Test metadata only. No names, words, URLs, paths or credentials.
begin isolation level repeatable read read only;
set local search_path='';set local timezone='UTC';set local statement_timeout='15s';set local row_security=off;
with context as(select transaction_timestamp() observed_at,'098d5b48-42a3-475b-b562-735c9eafce80'::uuid workspace_id),
series as(select s.id,s.workspace_id,s.output_type,s.audience_snapshot,s.template_key,s.template_version,s.template_content_sha256,s.latest_ready_version_id,s.latest_ready_version_no,s.next_version_number from eps.presentation_series s,context c where s.workspace_id=c.workspace_id),
versions as(select v.id,v.series_id,v.workspace_id,v.version_number,v.status,v.snapshot,v.manifest,v.snapshot_sha256,v.manifest_sha256,v.inventory_sha256,v.page_count,v.pdf_asset_id,v.manifest_asset_id from eps.presentation_versions v,context c where v.workspace_id=c.workspace_id),
links as(select l.id,l.series_id,l.label,l.created_at,l.expires_at,l.download_enabled,l.revoked_at,l.token_generation,l.export_revision,l.row_version from eps.review_links l join series s on s.id=l.series_id),
sessions as(select g.id,g.review_link_id,g.display_name,g.company,g.link_token_generation,g.created_at,g.expires_at,g.last_seen_at from eps.guest_sessions g join links l on l.id=g.review_link_id),
comments as(select f.id,f.series_id,f.version_id,f.slide_id,f.guest_session_id,f.parent_comment_id,f.visibility,f.resolved,f.deleted_at,f.row_version,f.created_at,f.updated_at from eps.feedback_comments f join series s on s.id=f.series_id),
preferences as(select f.id,f.series_id,f.version_id,f.slide_id,f.guest_session_id,f.preference,f.row_version from eps.feedback_preferences f join series s on s.id=f.series_id),
exports as(select e.id,e.version_id,e.review_link_id,e.template_version,e.export_revision,e.parent_token_generation,e.status,e.pdf_asset_id,e.media_grant_id,e.job_id,e.created_at,e.ready_at,e.failure_code from eps.presentation_exports e join links l on l.id=e.review_link_id),
grants as(select g.id,g.review_link_id,g.version_id,g.export_id,g.parent_token_generation,g.token_digest is not null token_digest_present,g.producing_attempt_id,g.created_at,g.expires_at,g.revoked_at from eps.review_media_grants g join links l on l.id=g.review_link_id)
select jsonb_build_object(
 'schema_version','1.0','observed_at',c.observed_at,'query_role',current_user,'database',current_database(),'workspace_id',c.workspace_id,
 'unrestricted_visibility',current_setting('row_security')='off'and exists(select 1 from pg_roles where rolname=current_user and(rolsuper or rolbypassrls)),
 'migration_versions',(select jsonb_agg(version order by version)from supabase_migrations.schema_migrations),
 'series',(select coalesce(jsonb_agg(jsonb_build_object('id',s.id,'workspace_id',s.workspace_id,'output_type',s.output_type,'audience_scope',s.audience_snapshot->>'scope',
  'template_version',s.template_version,'template_content_sha256',s.template_content_sha256,'latest_ready_version_id',s.latest_ready_version_id,'latest_ready_version_no',s.latest_ready_version_no,'next_version_no',s.next_version_number)order by s.id),'[]')from series s),
 'versions',(select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'series_id',v.series_id,'workspace_id',v.workspace_id,'version_no',v.version_number,'status',v.status,
  'snapshot_sha256',v.snapshot_sha256,'manifest_sha256',v.manifest_sha256,'inventory_sha256',v.inventory_sha256,
  'snapshot_hash_matches',v.snapshot_sha256=eps.presentation_hash(v.snapshot),'manifest_hash_matches',v.manifest_sha256=eps.presentation_hash(v.manifest),'inventory_hash_matches',v.inventory_sha256=eps.presentation_hash(v.snapshot->'asset_inventory'),
  'page_count',v.page_count,'template_version',v.snapshot#>>'{template,version}','template_content_sha256',v.snapshot#>>'{template,content_sha256}',
  'audience_scope',v.snapshot#>>'{audience_snapshot,scope}','snapshot_scope_matches_series',v.snapshot->>'series_id'=s.id::text and v.snapshot->'audience_snapshot'=s.audience_snapshot and v.snapshot#>>'{cover,output_type}'=s.output_type and v.snapshot#>>'{template,key}'=s.template_key and v.snapshot#>>'{template,version}'=s.template_version and v.snapshot#>>'{template,content_sha256}'=s.template_content_sha256,
  'slides',(select coalesce(jsonb_agg(jsonb_build_object('id',d.id,'order',d.ordinal,'kind',d.kind,'assignment_id',d.source_assignment_id,'slot_id',d.source_slot_id,'content_sha256',d.content_sha256,'frame_count',jsonb_array_length(d.snapshot->'frame_asset_ids'),'has_original_video',(d.snapshot->>'video_asset_id')is not null)order by d.ordinal),'[]')from eps.version_slides d where d.version_id=v.id),
  'pins',(select coalesce(jsonb_agg(jsonb_build_object('asset_id',p.asset_id,'asset_kind',p.asset_kind,'sha256',p.sha256,'byte_size',p.byte_size,'current_physical_identity_matches',a.bucket=p.bucket and a.object_key=p.object_key and a.sha256=p.sha256 and a.size_bytes=p.byte_size and a.mime_type=p.mime_type,'retained',a.status in('ready','archived'))order by p.asset_id),'[]')from eps.presentation_version_assets p join eps.media_assets a on a.id=p.asset_id where p.version_id=v.id),
  'pdf_asset_id',v.pdf_asset_id,'manifest_asset_id',v.manifest_asset_id,'pdf_sha256',a.sha256,'pdf_bytes',a.size_bytes,'manifest_bytes_sha256',m.sha256)order by v.series_id,v.version_number),'[]')from versions v join series s on s.id=v.series_id left join eps.media_assets a on a.id=v.pdf_asset_id left join eps.media_assets m on m.id=v.manifest_asset_id),
 'links',(select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'series_id',l.series_id,'label_present',length(l.label)>0,'label_codepoints',length(l.label),'created_at',l.created_at,'expires_at',l.expires_at,
  'expiry_default30_delta_ms',round(extract(epoch from(l.expires_at-l.created_at-interval'30days'))*1000)::bigint,'default_30_day_expiry',abs(extract(epoch from(l.expires_at-l.created_at-interval'30days')))<=1,
  'download_enabled',l.download_enabled,'revoked_at',l.revoked_at,'token_generation',l.token_generation,'export_revision',l.export_revision,'row_version',l.row_version,'live',l.revoked_at is null and l.expires_at>c.observed_at,'latest_ready_version_id',s.latest_ready_version_id,
  'session_count',(select count(*)from sessions g where g.review_link_id=l.id),'external_comment_count',(select count(*)from comments f join sessions g on g.id=f.guest_session_id where g.review_link_id=l.id and f.visibility='external'),'preference_count',(select count(*)from preferences f join sessions g on g.id=f.guest_session_id where g.review_link_id=l.id))order by l.id),'[]')from links l join series s on s.id=l.series_id),
 'sessions',(select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'review_link_id',g.review_link_id,'identified',g.display_name is not null,'company_present',coalesce(length(g.company),0)>0,'link_token_generation',g.link_token_generation,
  'created_at',g.created_at,'expires_at',g.expires_at,'last_seen_at',g.last_seen_at,'parent_generation_current',g.link_token_generation=l.token_generation,'active',g.expires_at>c.observed_at and g.link_token_generation=l.token_generation and l.revoked_at is null and l.expires_at>c.observed_at,
  'comment_count',(select count(*)from comments f where f.guest_session_id=g.id),'preference_count',(select count(*)from preferences f where f.guest_session_id=g.id))order by g.id),'[]')from sessions g join links l on l.id=g.review_link_id),
 'comments',(select coalesce(jsonb_agg(jsonb_build_object('id',f.id,'series_id',f.series_id,'version_id',f.version_id,'slide_id',f.slide_id,'guest_session_id',f.guest_session_id,'author_kind',case when f.guest_session_id is null then'internal'else'guest'end,'parent_comment_id',f.parent_comment_id,'visibility',f.visibility,'resolved',f.resolved,'deleted',f.deleted_at is not null,'row_version',f.row_version,'created_at',f.created_at,'updated_at',f.updated_at,'reply_count',(select count(*)from comments reply where reply.parent_comment_id=f.id))order by f.id),'[]')from comments f),
 'preferences',(select coalesce(jsonb_agg(jsonb_build_object('id',f.id,'series_id',f.series_id,'version_id',f.version_id,'slide_id',f.slide_id,'guest_session_id',f.guest_session_id,'author_kind',case when f.guest_session_id is null then'internal'else'guest'end,'preference',f.preference,'row_version',f.row_version)order by f.id),'[]')from preferences f),
 'exports',(select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'version_id',e.version_id,'review_link_id',e.review_link_id,'template_version',e.template_version,'export_revision',e.export_revision,'parent_token_generation',e.parent_token_generation,'current_cache_identity',e.parent_token_generation=l.token_generation and e.export_revision=l.export_revision,
  'status',e.status,'pdf_asset_id',e.pdf_asset_id,'pdf_sha256',a.sha256,'pdf_bytes',a.size_bytes,'pdf_identity_matches_job',case when a.id is null then null else a.producing_job_id=e.job_id and a.purpose='presentation_pdf'and a.output_stage='render_export'and a.status in('ready','archived')end,
  'canonical_pdf_unchanged',e.pdf_asset_id is distinct from v.pdf_asset_id,'media_grant_id',e.media_grant_id,'grant_digest_present',g.token_digest_present is true,'job_id',e.job_id,'created_at',e.created_at,'ready_at',e.ready_at,'failure_code',e.failure_code)order by e.id),'[]')from exports e join links l on l.id=e.review_link_id join versions v on v.id=e.version_id left join eps.media_assets a on a.id=e.pdf_asset_id left join grants g on g.id=e.media_grant_id),
 'media_grants',(select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'review_link_id',g.review_link_id,'version_id',g.version_id,'export_id',g.export_id,'parent_token_generation',g.parent_token_generation,'token_digest_present',g.token_digest_present,'producing_attempt_id',g.producing_attempt_id,'created_at',g.created_at,'expires_at',g.expires_at,'revoked_at',g.revoked_at,'parent_generation_current',g.parent_token_generation=l.token_generation,
  'live',g.revoked_at is null and g.expires_at>c.observed_at and g.parent_token_generation=l.token_generation and l.revoked_at is null and l.expires_at>c.observed_at,'published_export_member',e.media_grant_id=g.id and e.status='ready',
  'video_asset_ids',(select coalesce(jsonb_agg(p.asset_id order by p.asset_id),'[]')from eps.presentation_version_assets p where p.version_id=g.version_id and p.asset_kind='candidate_video'))order by g.id),'[]')from grants g join links l on l.id=g.review_link_id join exports e on e.id=g.export_id),
 'asset_grants',(select coalesce(jsonb_agg(jsonb_build_object('session_id',a.session_id,'media_grant_id',a.media_grant_id,'review_link_id',a.review_link_id,'version_id',a.version_id,'asset_id',a.asset_id,'export_id',a.export_id,'purpose',a.purpose,'created_at',a.created_at,'expires_at',a.expires_at,'token_digest_present',a.token_digest is not null,
  'fixed_asset_membership',case when a.purpose='pdf'then exists(select 1 from exports e where e.id=a.export_id and e.version_id=a.version_id and e.review_link_id=a.review_link_id and e.pdf_asset_id=a.asset_id)else exists(select 1 from eps.presentation_version_assets p where p.version_id=a.version_id and p.asset_id=a.asset_id and p.asset_kind=case a.purpose when'video'then'candidate_video'when'frame'then'candidate_frame'else'client_logo'end)end)order by a.created_at,a.asset_id),'[]')from eps.guest_asset_grants a join links l on l.id=a.review_link_id),
 'jobs',(select coalesce(jsonb_agg(jsonb_build_object('id',j.id,'workspace_id',j.workspace_id,'export_id',e.id,'kind',j.kind,'status',j.status,'stage',j.stage,'attempt',j.attempt,'current_attempt_id',j.current_attempt_id,'dispatch_generation',j.dispatch_generation,'n8n_execution_id',j.n8n_execution_id,'error_code',j.error->>'code','input_hash_matches',j.input_hash=eps.presentation_hash(j.input),
  'completed_stages',(select coalesce(jsonb_agg(jsonb_build_object('stage',s.value->>'stage','attempt_id',s.value->>'attempt_id','input_hash_matches',s.value->>'input_hash'=j.input_hash,'result_schema',s.value->>'result_schema')order by s.ordinal),'[]')from jsonb_array_elements(j.completed_stages)with ordinality s(value,ordinal)),
  'stage_receipts',(select coalesce(jsonb_agg(jsonb_build_object('stage',p.stage,'attempt_id',p.attempt_id,'result_schema',p.result_schema)order by p.attempt_id),'[]')from eps.review_stage_payloads p where p.job_id=j.id),
  'outbox',(select coalesce(jsonb_agg(jsonb_build_object('id',o.id,'stage',o.stage,'status',o.status,'generation',o.dispatch_generation,'attempt_count',o.attempt_count,'input_hash_matches',o.input_hash=j.input_hash)order by o.dispatch_generation),'[]')from eps.outbox_events o where o.job_id=j.id))order by j.id),'[]')from eps.jobs j join exports e on e.job_id=j.id where j.workspace_id=c.workspace_id and j.kind='presentation_export'),
 'protected',jsonb_build_object('m02_waiting_preserved',exists(select 1 from eps.jobs where id='b3f90268-147d-41d4-8875-2a6435df1496'and status='waiting_for_input'and error->>'code'='INPUT_CHANGED'),
  'm02_manual_note_retained',exists(select 1 from eps.jobs j join eps.specs s on s.id=j.resource_id and s.workspace_id=j.workspace_id where j.id='b3f90268-147d-41d4-8875-2a6435df1496'and position('Manual verification: preserve this instruction while extraction is pending.'in coalesce(s.normalized_instructions,''))>0),
  'owner_confirmed_profile_still_reviewed',exists(select 1 from eps.candidates where id='25a3c924-7b6c-48e3-88ce-c72e72b99c6d'and eps.cast_is_reviewed(candidates)),
  'reviewed_source_sha256',(select sha256 from eps.media_assets where id='5f8a6d53-0da0-4064-aacf-aea6b9c47c81'))
)as m06_app_capture from context c;
rollback;
